GO

-- Subject areas
INSERT canon.SubjectArea (SubjectAreaCode, Name, Description, SortOrder, CreatedBy)
SELECT v.c, v.n, v.d, v.s, N'SI2 seed'
FROM (VALUES
    (N'POLICY', N'Policy', N'The contract: policy term, status, transactions, forms.', 10),
    (N'PARTY', N'Party / Insured', N'People and organizations: insureds, drivers, claimants, employers.', 20),
    (N'LOCATION', N'Location / Address', N'Addresses, risk locations, territories, catastrophe zones.', 30),
    (N'VEHICLE', N'Vehicle', N'Vehicles and their use.', 40),
    (N'DRIVER', N'Driver', N'Drivers, licensing, violations and loss history.', 50),
    (N'PROPERTY', N'Property / Building', N'Buildings and property characteristics.', 60),
    (N'COVERAGE', N'Coverage', N'Coverages, limits, deductibles.', 70),
    (N'RATING', N'Rating', N'Rating variables, classes, factors and rates.', 80),
    (N'PREMIUM', N'Premium', N'Premium transactions and amounts.', 90),
    (N'UNDERWRITING', N'Underwriting', N'Submissions, risk scores, decisions and authority.', 100),
    (N'CLAIM', N'Claim', N'Claims, claimants and claim characteristics.', 110),
    (N'CLAIM_FINANCIAL', N'Claim Financials', N'Payments, reserves, recoveries and expenses.', 120),
    (N'WORKERS_COMP', N'Workers Compensation', N'WC policy, injury, benefit and medical data (WCIO / NCCI).', 130),
    (N'MEDICAL', N'Medical Billing', N'Medical bills, providers and procedures.', 140),
    (N'FRAUD', N'Fraud / SIU', N'Fraud scores, referrals and investigations.', 150),
    (N'PRODUCER', N'Producer / Distribution', N'Agents, brokers, channels and commissions.', 160),
    (N'BILLING', N'Billing', N'Invoices, payment plans and payments.', 170),
    (N'REINSURANCE', N'Reinsurance', N'Treaties, layers, cessions and reinsurers.', 180),
    (N'CAPITAL', N'Risk & Capital', N'Capital, solvency and risk appetite measures.', 190),
    (N'BUREAU', N'Bureau Reporting', N'Bureau-only technical fields (record control, filler, company use).', 200)
) v (c, n, d, s)
WHERE NOT EXISTS (SELECT 1 FROM canon.SubjectArea x WHERE x.SubjectAreaCode = v.c);

