JOIN canon.PickList p ON p.PickListCode = v.pl AND p.ScopeId = 1
JOIN canon.PickListOption o ON o.PickListId = p.PickListId AND o.OptionCode = v.oc AND o.LobScope = v.lob AND o.ScopeId = 1
WHERE NOT EXISTS (SELECT 1 FROM canon.BureauCodeMap x WHERE x.OptionId = o.OptionId AND x.Bureau = v.b AND x.LobScope = v.lob);

