LEFT JOIN canon.PickList p ON p.PickListCode = v.pl AND p.ScopeId = 1
WHERE NOT EXISTS (SELECT 1 FROM canon.DataElement x WHERE x.ElementCode = v.c AND x.ScopeId = 1);

