CROSS APPLY (SELECT CASE v.ot
    WHEN 'ELEMENT' THEN (SELECT ElementId FROM canon.DataElement WHERE ElementCode = v.oc AND ScopeId = 1)
    WHEN 'PICKLIST' THEN (SELECT PickListId FROM canon.PickList WHERE PickListCode = v.oc AND ScopeId = 1)
    WHEN 'OPTION' THEN (SELECT TOP (1) o.OptionId FROM canon.PickListOption o JOIN canon.PickList p ON p.PickListId = o.PickListId
                        WHERE p.PickListCode = v.pl AND p.ScopeId = 1 AND o.OptionCode = v.oc AND o.ScopeId = 1 ORDER BY o.OptionId) END AS Id) x
WHERE x.Id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM canon.Synonym s WHERE s.ObjectType = v.ot AND s.ObjectId = x.Id AND s.SynonymText = v.t AND s.SourceSystem = v.src AND s.ScopeId = 1);

