-- Extension attributes
INSERT canon.ExtensionAttribute (ObjectType, ObjectId, AttributeName, AttributeValue, CreatedBy)
SELECT v.ot, e.ElementId, v.n, v.val, N'SI2 seed'
FROM (VALUES
    (N'ELEMENT', CAST(NULL AS nvarchar(4000)), N'CLAIM_STATUS', N'NCCI pick list', N'NCCI_CLAIM_STATUS_CODE'),
    (N'ELEMENT', NULL, N'DEDUCTIBLE_TYPE', N'NCCI pick list', N'NCCI_LOSSES_SUBJECT_TO_DEDUCTIBLE_CODE'),
    (N'ELEMENT', NULL, N'LEGAL_NATURE_INSURED', N'NCCI pick list', N'NCCI_LEGAL_NATURE_OF_ENTITY_CODE'),
    (N'ELEMENT', NULL, N'LUMP_SUM_INDICATOR', N'NCCI pick list', N'NCCI_LUMP_SUM_INDICATOR'),
    (N'ELEMENT', NULL, N'RETROSPECTIVE_RATED', N'NCCI pick list', N'NCCI_RETROSPECTIVE_RATED_POLICY_INDICATOR; NCCI_RETROSPECTIVE_RATING_CODE'),
    (N'ELEMENT', NULL, N'TRANSACTION_TYPE', N'NCCI pick list', N'NCCI_TRANSACTION_CODE')
) v (ot, pl, oc, n, val)
JOIN canon.DataElement e ON e.ElementCode = v.oc AND e.ScopeId = 1
WHERE NOT EXISTS (SELECT 1 FROM canon.ExtensionAttribute x WHERE x.ObjectType = v.ot AND x.ObjectId = e.ElementId AND x.AttributeName = v.n AND x.ScopeId = 1);

-- Rule sets
INSERT rules.RuleSet (RuleSetCode, Name, Purpose, Description, CreatedBy)
SELECT v.c, v.n, v.p, v.d, N'SI2 seed'
FROM (VALUES
    (N'ISO_BUREAU', N'ISO statistical reporting', N'BUREAU', N'Derivations, transformations and validations for ISO statistical plans (all lines).'),
    (N'NCCI_EDITS', N'NCCI / WCIO data edits', N'BUREAU', N'Edits a DCO applies to WCSTAT, WCPOLS, WCIND and WCMED submissions (SI² edit IDs).'),
    (N'UW_PERSONAL_AUTO', N'Personal auto underwriting', N'UNDERWRITING', N'Eligibility, referral and pricing rules for personal auto.'),
    (N'ROLE_AUTHORITY', N'Role decision boundaries', N'UNDERWRITING', N'Authority and appetite boundaries each role works within; changes need a second person.'),
    (N'CLAIMS_TRIAGE', N'Claims triage and routing', N'CLAIMS', N'Routing of new and open claims to fast track, complex handling or SIU.'),
    (N'DATA_QUALITY', N'Data quality', N'DATA_QUALITY', N'Checks applied to every load before data reaches the company model.')
) v (c, n, p, d)
WHERE NOT EXISTS (SELECT 1 FROM rules.RuleSet x WHERE x.RuleSetCode = v.c AND x.ScopeId = 1);

-- Rules
INSERT rules.BusinessRule (RuleSetId, RuleCode, Name, Description, RuleType, LobScope, StateScope, TargetElementId, ConditionLogic,
    ConditionText, ActionType, ActionValue, Severity, Message, Priority, ExpressionJson, EffectiveFrom, CreatedBy)
SELECT rs.RuleSetId, v.c, v.n, v.d, v.t, v.lob, v.st, e.ElementId, v.lg, v.ct, v.a, v.av, v.sev, v.m, v.p, v.x, v.ef, N'SI2 seed'
FROM (VALUES
    (N'ISO_BUREAU', N'DR001', N'Derive ISO line of business', N'Line of business comes from the line the SME selected for the run.', N'DERIVATION', N'*', N'*', N'LINE_OF_BUSINESS', N'ALL', CAST(NULL AS nvarchar(4000)), N'SET_VALUE', CAST(NULL AS nvarchar(4000)), N'ERROR', CAST(NULL AS nvarchar(4000)), 100, N'{"op": "set", "value": "$batch.lob"}', N'2020-01-01'),
    (N'ISO_BUREAU', N'DR002', N'Derive auto bureau sub-line from coverage', N'Auto liability coverages report as AL, PIP/no-fault as AN, collision and comprehensive as AP.', N'DERIVATION', N'PA,CA', N'*', N'MAJOR_LINE', N'ALL', NULL, N'LOOKUP', NULL, N'ERROR', N'Coverage cannot be assigned to AL/AN/AP', 100, N'{"op": "lookup", "from": "COVERAGE", "map": {"BI": "AL", "PD": "AL", "CSL": "AL", "UM": "AL", "MED": "AL", "PIP": "AN", "COLL": "AP", "COMP": "AP"}}', N'2020-01-01'),
    (N'ISO_BUREAU', N'DR003', N'Derive major line for non-auto lines', N'Each non-auto line reports a single major line code equal to its line abbreviation.', N'DERIVATION', N'CP,GL,IM,CR,HO,BP,FI,BR', N'*', N'MAJOR_LINE', N'ALL', NULL, N'SET_VALUE', NULL, N'ERROR', NULL, 100, N'{"op": "set", "value": "$lob.major_line"}', N'2020-01-01'),
    (N'ISO_BUREAU', N'DR004', N'Auto loss coverage from cause of loss', N'If a loss record has no coverage, the type of loss identifies it (BI, PD, PIP, COLL, COMP, UM).', N'DERIVATION', N'PA,CA', N'*', N'COVERAGE_CODE', N'ALL', NULL, N'SET_VALUE', NULL, N'ERROR', NULL, 100, N'{"op": "coalesce", "from": ["COVERAGE", "CAUSE_OF_LOSS"]}', N'2020-01-01'),
    (N'ISO_BUREAU', N'DR005', N'Filler is blank', N'ISO reserved / extension positions are space-filled until an extension is approved.', N'DERIVATION', N'*', N'*', NULL, N'ALL', NULL, N'SET_VALUE', NULL, N'ERROR', NULL, 100, N'{"op": "set", "value": ""}', N'2020-01-01'),
