    (N'DATA_QUALITY', N'DQ_POLICY_NUMBER', N'Policy number is required', N'Policy number is required.', N'VALIDATION', N'*', N'*', NULL, N'ALL', N'POLICY_NUMBER IS NULL None', N'REJECT', NULL, N'ERROR', N'Policy number is required', 100, NULL, N'2020-01-01'),
    (N'DATA_QUALITY', N'DQ_EXP_DATE', N'Expiration date is required', N'Expiration date is required.', N'VALIDATION', N'*', N'*', NULL, N'ALL', N'POLICY_EXPIRATION_DATE IS NULL None', N'REJECT', NULL, N'ERROR', N'Expiration date is required', 100, NULL, N'2020-01-01'),
    (N'DATA_QUALITY', N'DQ_ZIP', N'ZIP code must start with five digits', N'ZIP code must start with five digits.', N'VALIDATION', N'*', N'*', NULL, N'ALL', N'ZIP_CODE NOT LIKE [0-9][0-9][0-9][0-9][0-9]%', N'REJECT', NULL, N'ERROR', N'ZIP code must start with five digits', 100, NULL, N'2020-01-01'),
    (N'DATA_QUALITY', N'DQ_VIN', N'VIN must be 17 characters', N'VIN must be 17 characters.', N'VALIDATION', N'*', N'*', NULL, N'ALL', N'VIN NOT LIKE _________________', N'WARN', NULL, N'WARNING', N'VIN must be 17 characters', 100, NULL, N'2020-01-01'),
    (N'DATA_QUALITY', N'DQ_MODEL_YEAR', N'Model year before 1981 (pre-VIN standard)', N'Model year before 1981 (pre-VIN standard).', N'VALIDATION', N'*', N'*', NULL, N'ALL', N'VEHICLE_MODEL_YEAR < 1981', N'WARN', NULL, N'WARNING', N'Model year before 1981 (pre-VIN standard)', 100, NULL, N'2020-01-01'),
    (N'DATA_QUALITY', N'DQ_NEG_PAID', N'Paid loss is negative', N'Paid loss is negative.', N'VALIDATION', N'*', N'*', NULL, N'ALL', N'PAID_LOSS < 0', N'WARN', NULL, N'WARNING', N'Paid loss is negative', 100, NULL, N'2020-01-01'),
    (N'DATA_QUALITY', N'DQ_LOSS_DATE', N'Loss date is required', N'Loss date is required.', N'VALIDATION', N'*', N'*', NULL, N'ALL', N'LOSS_DATE IS NULL None', N'REJECT', NULL, N'ERROR', N'Loss date is required', 100, NULL, N'2020-01-01')
) v (rs, c, n, d, t, lob, st, te, lg, ct, a, av, sev, m, p, x, ef)
JOIN rules.RuleSet rs ON rs.RuleSetCode = v.rs AND rs.ScopeId = 1
LEFT JOIN canon.DataElement e ON e.ElementCode = v.te AND e.ScopeId = 1
WHERE NOT EXISTS (SELECT 1 FROM rules.BusinessRule x WHERE x.RuleCode = v.c AND x.ScopeId = 1);

-- Rule conditions
INSERT rules.RuleCondition (RuleId, Seq, ElementId, Operator, Value1, Value2, CreatedBy)
SELECT r.RuleId, v.s, e.ElementId, v.o, v.v1, v.v2, N'SI2 seed'
FROM (VALUES
    (N'R01', 1, N'STATE', N'NOT IN', N'FL,GA,NC,NY,OH,TX', CAST(NULL AS nvarchar(4000))),
    (N'R02', 1, N'PRIOR_CLAIMS', N'>=', N'3', NULL),
    (N'R03', 1, N'VEHICLE_USE', N'=', N'RIDESHARE', NULL),
    (N'R04', 1, N'DRIVER_AGE', N'<', N'21', NULL),
    (N'R04', 2, N'VEHICLE_VALUE', N'>', N'40000', NULL),
    (N'R05', 1, N'VIOLATIONS', N'>=', N'2', NULL),
    (N'R06', 1, N'COVERAGE_LAPSE_DAYS', N'>', N'30', NULL),
    (N'R07', 1, N'ANNUAL_MILES', N'>', N'25000', NULL),
    (N'R08', 1, N'YEARS_LICENSED', N'>=', N'10', NULL),
    (N'R08', 2, N'PRIOR_CLAIMS', N'=', N'0', NULL),
    (N'R08', 3, N'VIOLATIONS', N'=', N'0', NULL),
    (N'R09', 1, N'TELEMATICS_SCORE', N'<', N'40', NULL),
    (N'R09', 2, N'VEHICLE_USE', N'=', N'DELIVERY', NULL),
    (N'R10', 1, N'DRIVER_AGE', N'>=', N'80', NULL),
    (N'R10', 2, N'VIOLATIONS', N'>=', N'1', NULL),
    (N'R11', 1, N'STATE', N'=', N'FL', NULL),
    (N'R11', 2, N'ANNUAL_MILES', N'>', N'20000', NULL),
    (N'UW_AUTH_TIV', 1, N'TOTAL_INSURED_VALUE', N'>', N'2000000', NULL),
    (N'UW_ACCEPT', 1, N'RISK_SCORE', N'<=', N'55', NULL),
    (N'UW_DECLINE', 1, N'RISK_SCORE', N'>=', N'85', NULL),
    (N'UW_REFER_BAND', 1, N'RISK_SCORE', N'BETWEEN', N'55.01', N'84.99'),
    (N'CL_RESERVE_AUTH', 1, N'RESERVE_CHANGE_AMOUNT', N'>', N'25000', NULL),
    (N'ERM_MIN_SOLVENCY', 1, N'SOLVENCY_RATIO', N'<', N'1.5', NULL),
    (N'ERM_NET_CAT', 1, N'NET_CAT_1_IN_200', N'>', N'225000000', NULL),
    (N'CT_SIU', 1, N'FRAUD_SCORE', N'>=', N'80', NULL),
    (N'CT_COMPLEX_ATTY', 1, N'ATTORNEY_INDICATOR', N'=', N'Y', NULL),
    (N'CT_COMPLEX_SIZE', 1, N'INCURRED_LOSS', N'>', N'60000', NULL),
    (N'CT_FAST', 1, N'INCURRED_LOSS', N'<', N'5000', NULL),
    (N'CT_FAST', 2, N'ATTORNEY_INDICATOR', N'=', N'N', NULL),
    (N'DQ_POLICY_NUMBER', 1, N'POLICY_NUMBER', N'IS NULL', NULL, NULL),
    (N'DQ_EXP_DATE', 1, N'POLICY_EXPIRATION_DATE', N'IS NULL', NULL, NULL),
    (N'DQ_ZIP', 1, N'ZIP_CODE', N'NOT LIKE', N'[0-9][0-9][0-9][0-9][0-9]%', NULL),
    (N'DQ_VIN', 1, N'VIN', N'NOT LIKE', N'_________________', NULL),
    (N'DQ_MODEL_YEAR', 1, N'VEHICLE_MODEL_YEAR', N'<', N'1981', NULL),
    (N'DQ_NEG_PAID', 1, N'PAID_LOSS', N'<', N'0', NULL),
    (N'DQ_LOSS_DATE', 1, N'LOSS_DATE', N'IS NULL', NULL, NULL)
) v (r, s, e, o, v1, v2)
JOIN rules.BusinessRule r ON r.RuleCode = v.r AND r.ScopeId = 1
JOIN canon.DataElement e ON e.ElementCode = v.e AND e.ScopeId = 1
WHERE NOT EXISTS (SELECT 1 FROM rules.RuleCondition x WHERE x.RuleId = r.RuleId AND x.Seq = v.s);

-- Rule test cases
INSERT rules.RuleTestCase (RuleId, Name, InputJson, ExpectedFires, CreatedBy)
SELECT r.RuleId, v.n, v.j, v.x, N'SI2 seed'
FROM (VALUES
    (N'R01', N'Ineligible state: fires', N'{"STATE": "CA"}', 1),
    (N'R01', N'Ineligible state: does not fire', N'{"STATE": "TX"}', 0),
    (N'R02', N'Frequent claims: fires', N'{"PRIOR_CLAIMS": 3}', 1),
    (N'R02', N'Frequent claims: does not fire', N'{"PRIOR_CLAIMS": 1}', 0),
    (N'R03', N'Rideshare use: fires', N'{"VEHICLE_USE": "RIDESHARE"}', 1),
    (N'R03', N'Rideshare use: does not fire', N'{"VEHICLE_USE": "COMMUTE"}', 0),
    (N'R04', N'Young driver, high-value vehicle: fires', N'{"DRIVER_AGE": 19, "VEHICLE_VALUE": 45000}', 1),
    (N'R04', N'Young driver, high-value vehicle: does not fire', N'{"DRIVER_AGE": 19, "VEHICLE_VALUE": 18000}', 0),
    (N'R05', N'Multiple violations: fires', N'{"VIOLATIONS": 2}', 1),
    (N'R05', N'Multiple violations: does not fire', N'{"VIOLATIONS": 1}', 0),
    (N'R06', N'Lapse in coverage: fires', N'{"COVERAGE_LAPSE_DAYS": 45}', 1),
    (N'R06', N'Lapse in coverage: does not fire', N'{"COVERAGE_LAPSE_DAYS": 10}', 0),
    (N'R07', N'High annual mileage: fires', N'{"ANNUAL_MILES": 30000}', 1),
    (N'R07', N'High annual mileage: does not fire', N'{"ANNUAL_MILES": 12000}', 0),
    (N'R08', N'Experienced clean driver: fires', N'{"YEARS_LICENSED": 15, "PRIOR_CLAIMS": 0, "VIOLATIONS": 0}', 1),
    (N'R08', N'Experienced clean driver: does not fire', N'{"YEARS_LICENSED": 15, "PRIOR_CLAIMS": 1, "VIOLATIONS": 0}', 0),
    (N'R09', N'Low telematics score on delivery use: fires', N'{"TELEMATICS_SCORE": 32, "VEHICLE_USE": "DELIVERY"}', 1),
    (N'R09', N'Low telematics score on delivery use: does not fire', N'{"TELEMATICS_SCORE": 32, "VEHICLE_USE": "PLEASURE"}', 0),
    (N'R10', N'Senior driver with a violation: fires', N'{"DRIVER_AGE": 82, "VIOLATIONS": 1}', 1),
    (N'R10', N'Senior driver with a violation: does not fire', N'{"DRIVER_AGE": 82, "VIOLATIONS": 0}', 0),
    (N'R11', N'Florida high mileage: fires', N'{"STATE": "FL", "ANNUAL_MILES": 22000}', 1),
    (N'R11', N'Florida high mileage: does not fire', N'{"STATE": "GA", "ANNUAL_MILES": 22000}', 0),
    (N'UW_AUTH_TIV', N'TIV $3M: refer', N'{"TOTAL_INSURED_VALUE": 3000000}', 1),
    (N'UW_AUTH_TIV', N'TIV $1M: within authority', N'{"TOTAL_INSURED_VALUE": 1000000}', 0),
    (N'CL_RESERVE_AUTH', N'Change $40,000: route', N'{"RESERVE_CHANGE_AMOUNT": 40000}', 1),
    (N'CL_RESERVE_AUTH', N'Change $8,000: adjuster decides', N'{"RESERVE_CHANGE_AMOUNT": 8000}', 0),
    (N'UW_REFER_BAND', N'Score 70: refer', N'{"RISK_SCORE": 70}', 1),
    (N'ERM_MIN_SOLVENCY', N'Gross 0.74: warn', N'{"SOLVENCY_RATIO": 0.74}', 1),
    (N'CT_FAST', N'$2,500, no attorney: fast track', N'{"INCURRED_LOSS": 2500, "ATTORNEY_INDICATOR": "N"}', 1),
    (N'CT_FAST', N'$2,500 with attorney: not fast track', N'{"INCURRED_LOSS": 2500, "ATTORNEY_INDICATOR": "Y"}', 0),
    (N'CT_SIU', N'Fraud score 91: SIU', N'{"FRAUD_SCORE": 91}', 1),
    (N'DQ_ZIP', N'ZIP 3021: rejected', N'{"ZIP_CODE": "3021"}', 1),
    (N'DQ_ZIP', N'ZIP 30214: passes', N'{"ZIP_CODE": "30214"}', 0),
    (N'DQ_VIN', N'16-character VIN: warn', N'{"VIN": "1HGCM82633A00435"}', 1),
    (N'DQ_VIN', N'17-character VIN: passes', N'{"VIN": "1HGCM82633A004352"}', 0)
) v (r, n, j, x)
JOIN rules.BusinessRule r ON r.RuleCode = v.r AND r.ScopeId = 1
WHERE NOT EXISTS (SELECT 1 FROM rules.RuleTestCase x WHERE x.RuleId = r.RuleId AND x.Name = v.n);

-- Source systems
INSERT intake.SourceSystem (SourceSystemCode, Name, Kind, Notes, CreatedBy)
SELECT v.c, v.n, v.k, v.d, N'SI2 seed'
FROM (VALUES
    (N'Guidewire', N'Guidewire PolicyCenter / ClaimCenter', N'APP', N'Source names captured from mapping work.'),
    (N'DuckCreek', N'Duck Creek Policy / Claims', N'APP', N'Source names captured from mapping work.'),
    (N'Legacy', N'Legacy mainframe (COBOL copybooks, code tables)', N'FILE', NULL),
    (N'SI2 Cloud', N'SI² cloud canonical model (migration target)', N'APP', NULL),
    (N'ISO', N'ISO statistical plans', N'BUREAU', NULL),
    (N'NCCI', N'NCCI / WCIO specifications', N'BUREAU', NULL)
) v (c, n, k, d)
WHERE NOT EXISTS (SELECT 1 FROM intake.SourceSystem x WHERE x.SourceSystemCode = v.c);

